import pathlib,json,datetime,statistics,xml.etree.ElementTree as ET
ROOT=pathlib.Path(__file__).parent
access=json.loads((ROOT/'elsevier_latest_access.json').read_text(encoding='utf8'))
articles=json.loads((ROOT/'elsevier_article_date_results.json').read_text(encoding='utf8'))
jem=[x for x in articles if x.get('days')is not None]
assert len(jem)==2 and all(x['days']==89 for x in jem)
assert len(set(x['doi']for x in jem))==1
pmc=ET.fromstring((ROOT/'elsevier_jnc_epmc_xml.txt').read_text(encoding='utf8'))
history=' '.join(pmc.find('./front/notes').itertext())
assert 'Received 2025 Nov 7; Revised 2026 Apr 14; Accepted 2026 Apr 15.'in history
cases=[{'journal':'Journal for Nature Conservation','doi':'10.1016/j.jnc.2026.127304','title':'Rewilding reshapes gut microbiomes and parasite exposure in European bison: a 17-month release from Wilder Blean','received':'2025-11-07','accepted':'2026-04-15','days':159,'source_type':'PMC official archive of Elsevier-published full text; is-manuscript=no','source_url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC13276717/','xml_url':'https://www.ebi.ac.uk/europepmc/webservices/rest/PMC13276717/fullTextXML','exact_quote':'Received 2025 Nov 7; Revised 2026 Apr 14; Accepted 2026 Apr 15.','local_snapshot':'elsevier_jnc_epmc_xml.txt','limitation':'单篇原始研究，欧洲野牛再野化/微生物组，题材不同；非全刊统计。'},
{'journal':'Journal of Environmental Management','doi':'10.1016/j.jenvman.2026.131156','title':'Understanding public preferences for urban wildflower meadows','received':'2026-07-13','accepted':'2026-10-10','days':89,'source_type':'Publisher PDF in Imperial College and University of Kent repositories; same article independently checked twice','source_url':'https://spiral.imperial.ac.uk/server/api/core/bitstreams/8ebd20d6-e37f-442d-bdbc-a35427f92681/content','second_source_url':'https://kar.kent.ac.uk/117287/1/1-s2.0-S0301479726026162-main.pdf','exact_quote':'Received 13 July 2026; Received in revised form 28 September 2026; Accepted 10 October 2026','local_snapshot':'elsevier_article_10_1016_j_jenvman_2026_131156_2.dat','limitation':'单篇Research article，都市野花草甸公众偏好，题材相关；两个机构库是同一篇，不可当n=2；非全刊统计。'}]
for c in cases:assert(datetime.date.fromisoformat(c['accepted'])-datetime.date.fromisoformat(c['received'])).days==c['days']
evidence={'checked_date':'2026-11-09','overall_submission_to_acceptance_verified':False,'official_overall_results':[{'journal':n,'submission_to_acceptance_days':None,'reason':'Official Insights and alternate/legacy official routes all returned403; no correct overall metric obtained'}for n in ['Journal for Nature Conservation','Journal of Environmental Management']],'access_log':access,'verified_article_histories':cases,'excluded_metrics':'First decision, decision after review and Finder timeToAcceptance with inconsistent labels were not used.','scope_limit':'本次只核两刊接收总历时，不重做选刊。已存新快照、未改旧报告。'}
(ROOT/'elsevier_verified_evidence.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2),encoding='utf8')
lines=['# JNC与JEM投稿至接收时间复核','','访问日期：2026年11月9日。仅核Received/Submission → Accepted，不以初决、外审后决定或接收后出版代替。','','## 可报告结论','','**两刊最新官方全刊Submission to acceptance天数仍未核实，不能负责任地给出全刊数字。** 正式Insights、publish/insights、官网主页、出版社Elsevier入口及legacy Journal Insights各5个页面，本次均HTTP403。具体URL、时间和返回快照见elsevier_latest_access.json及elsevier_*.html。没有沿用旧Finder标签冲突字段。','','另取得两篇可核实的原刊历史，各期刊一篇：','','|期刊|论文|Received|Accepted|投稿至接收|证据性质|','|---|---|---|---|---:|---|']
for c in cases:lines.append(f"|{c['journal']}|[{c['title']}](https://doi.org/{c['doi']})|{c['received']}|{c['accepted']}|{c['days']}天|{c['source_type']}|")
lines += ['','这些天数都是单篇已接收研究论文的实际历时，包含作者修稿时间，不能当作全刊平均数、中位数或您的论文预计接收时间。JNC样本为生态学/微生物组实证研究，与公园治理问卷题材不同；JEM样本为都市野花草甸公众偏好研究，题材较接近，但仍不足以代表全刊。','','## 原始证据','','JNC：','',f"- 官方PMC全文：[PMC13276717]({cases[0]['source_url']})",f"- 官方EuropePMC XML：[fullTextXML]({cases[0]['xml_url']})",f"- 原句：`{cases[0]['exact_quote']}`",'- XML期刊名为Journal for Nature Conservation、DOI为10.1016/j.jnc.2026.127304，custom-meta显示is-manuscript=no、is-preprint=no。','','JEM：','',f"- [Imperial机构库原刊PDF]({cases[1]['source_url']})",f"- [Kent机构库原刊PDF]({cases[1]['second_source_url']})",f"- 原句：`{cases[1]['exact_quote']}`",'- 原刊第一页标明Research article，题名、DOI、日期一致；Kent封面明确Publisher pdf。两个机构库存档为同一论文，样本量为1。','','## 官网页面','','- https://www.sciencedirect.com/journal/journal-for-nature-conservation/about/insights','- https://www.sciencedirect.com/journal/journal-of-environmental-management/about/insights','','若要简短答复，可写：“目前未核得两刊官网全刊投稿至接收统计。可确认的近期单篇样本为JNC159天、JEM89天；不能据此说两刊通常各需159天和89天。”']
(ROOT/'elsevier_verified_evidence.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
print('Saved evidence: JNC sample159 days; JEM sample89 days; overall metrics unverified.')
